// Original RemoteWise editorial guides. Vendor descriptions are based on linked public documentation.
const ref=(name,url)=>[name,url];
const ftc=ref('FTC: recognising job scams','https://consumer.ftc.gov/articles/job-scams');
const locations=ref('Himalayas: searching by location and timezone','https://himalayas.app/docs/getting-started-job-seekers');
const pmrefs=[ref('Trello plans','https://trello.com/pricing'),ref('Asana plans','https://asana.com/pricing'),ref('ClickUp plans','https://clickup.com/pricing'),ref('Notion plans','https://www.notion.com/pricing')];
module.exports=[
{s:'international-remote-job-websites',t:'15 Websites to Find International Remote Jobs',c:'remote-jobs',d:'Compare job boards and freelance marketplaces, check country eligibility, and build a focused weekly search.',tools:['linkedin','upwork'],body:[
['Start with eligibility, not the word remote','A remote vacancy can still require residence in a particular country. Before tailoring your CV, check the permitted work location, working hours, employment arrangement and required experience. An employer’s headquarters tells you where the company is based; it does not tell you where you may work. Use the directory below as a search starting point, not a promise that every listing accepts international applicants.'],
['The 15 websites',{headers:['Website','Useful starting point','Check before applying'],rows:[
['<a href="https://weworkremotely.com/" target="_blank" rel="noopener noreferrer">We Work Remotely</a>','Remote vacancy browsing','Read the listing’s country or regional label.'],
['<a href="https://remoteok.com/" target="_blank" rel="noopener noreferrer">Remote OK</a>','Role and keyword searches','A remote label does not establish worldwide eligibility.'],
['<a href="https://remotive.com/" target="_blank" rel="noopener noreferrer">Remotive</a>','Location-filtered searching','Use your actual location; check any access charges.'],
['<a href="https://www.workingnomads.com/jobs" target="_blank" rel="noopener noreferrer">Working Nomads</a>','Remote job categories','Confirm the arrangement and any premium features.'],
['<a href="https://himalayas.app/jobs/worldwide" target="_blank" rel="noopener noreferrer">Himalayas</a>','Worldwide and country filters','Check timezone overlap in the employer’s description.'],
['<a href="https://jobspresso.co/" target="_blank" rel="noopener noreferrer">Jobspresso</a>','Support, technology and other categories','Follow through to the employer’s application page.'],
['<a href="https://remote.co/" target="_blank" rel="noopener noreferrer">Remote.co</a>','Remote and hybrid searches','Distinguish fully remote roles from hybrid work.'],
['<a href="https://www.flexjobs.com/" target="_blank" rel="noopener noreferrer">FlexJobs</a>','Flexible-work searching','Review subscription, renewal and cancellation terms.'],
['<a href="https://justremote.co/" target="_blank" rel="noopener noreferrer">JustRemote</a>','Fully and partially remote listings','Check workplace attendance and paid search options.'],
['<a href="https://wellfound.com/jobs" target="_blank" rel="noopener noreferrer">Wellfound</a>','Startup opportunities','Confirm hiring countries and stage of the business.'],
['<a href="https://www.linkedin.com/jobs/" target="_blank" rel="noopener noreferrer">LinkedIn Jobs</a>','Employer and recruiter research','Check the company’s own careers page as well.'],
['<a href="https://www.indeed.com/" target="_blank" rel="noopener noreferrer">Indeed</a>','Broad job-title searches','Country versions and location filters affect results.'],
['<a href="https://www.upwork.com/" target="_blank" rel="noopener noreferrer">Upwork</a>','Freelance projects','Check account eligibility, proposal costs and service fees.'],
['<a href="https://arc.dev/remote-jobs" target="_blank" rel="noopener noreferrer">Arc</a>','Specialist remote opportunities','Check professional fit and any screening requirements.'],
['<a href="https://www.toptal.com/talent/apply" target="_blank" rel="noopener noreferrer">Toptal</a>','Experienced freelance professionals','Review the application and selection process.']]}],
['Choose three channels for the first week','Try one remote-focused board, one broad platform and direct employer careers pages. Save two precise searches, such as customer support plus your country and operations coordinator plus remote. Spend your effort on eligible roles rather than registering everywhere. The directory includes boards and freelance marketplaces; they are different ways of finding work, not interchangeable employment services.'],
['Use a repeatable application check',['Confirm the listing appears on the real employer website, where available.','Record country restrictions and timezone requirements.','Save the role description before it expires.','Tailor your summary and two relevant achievements.','Track employer, role, URL, application date, status and follow-up date.']],
['Watch for recruitment scams','Do not send money to a recruiter to secure a vacancy. Treat requests to buy equipment through a specified seller, cash a cheque or forward money as warning signs. A paid job-board subscription is different from a recruiter demanding a placement payment, but you should still understand the subscription before paying. Check identities independently and share identity documents only through a verified hiring process.'],
['Your next step','Shortlist five roles that clearly match your location and skills. If none qualify, change the role keywords or country filter before buying a course or subscription. A smaller list of realistic applications is more useful than a large list of inaccessible vacancies.']
],refs:[locations,ref('Remotive: location filters','https://support.remotive.com/en/article/how-to-use-filters-9vh8i1/'),ftc]},
{s:'best-remote-jobs-for-beginners',t:'Best Remote Jobs for Beginners',c:'remote-jobs',d:'Choose an entry-level remote role based on your existing skills and build work samples before applying.',tools:['linkedin'],body:[
['What beginner actually means','Beginner-friendly usually means you can demonstrate the core tasks without years in that specific job title. It does not mean no preparation, guaranteed hiring or unrestricted international employment. Start with the skills you already use at work, in study or in community activities. Someone who coordinates appointments may be closer to an administrative role than to a technical support position.'],
['Compare possible starting roles',{headers:['Role','Useful starting skills','Work sample to create'],rows:[['Customer support','Clear writing, patience and problem diagnosis','Five sample replies and an escalation note.'],['Virtual administration','Scheduling, email and accurate records','A weekly calendar and meeting action log.'],['Social media coordination','Writing, organisation and basic design','A one-week content plan with three sample posts.'],['Junior content support','Research, proofreading and source checking','An edited article with a source list.'],['Data administration','Spreadsheets and attention to detail','A cleaned sample dataset with a quality checklist.']]}],
['Pick a role with a realistic practice task','Read several current vacancies and highlight repeated tasks. Choose one task you can practise with invented or public information. For example, create a customer enquiry log with categories, response deadlines and a short handover note. Explain the decisions you made. A small finished example is stronger than saying you are a fast learner without evidence. Never use a former employer’s confidential records in a portfolio.'],
['A two-week preparation plan',['Days 1–3: choose one role, review eligible vacancies and list missing skills.','Days 4–7: create one realistic sample and correct mistakes.','Days 8–10: write a targeted CV and a short portfolio explanation.','Days 11–14: submit a manageable number of tailored applications and record results.']],
['Show transferable experience','Use real responsibilities rather than inventing a remote background. A retail worker might describe handling enquiries, keeping records and resolving stock discrepancies. A student might show coordinating a group project and meeting deadlines. Describe the task, how you approached it and the result you can support. If you have no measured result, explain the completed deliverable without adding an invented percentage.'],
['Check the working arrangement','Ask whether the role is employment or freelance work, what equipment you need and which hours are fixed. Entry-level customer roles may involve evenings, weekends or voice calls. A job that suits your skills may still be unsuitable for your available hours or internet connection. Pay and eligibility vary, so use current employer information rather than generic salary promises.'],
['Avoid the easy-income trap','Be cautious of high earnings for basic clicking, product reshipping or tasks requiring deposits. Verify the business and recruiter before sharing documents. If a test task is substantial, clarify its purpose, duration and whether it is paid before committing.']
],refs:[locations,ftc]},
{s:'professional-cv-for-remote-jobs',t:'How to Create a Professional CV for Remote Jobs',c:'resume-cv',d:'Build a clear, targeted remote-work CV using a practical structure, fictional example and final review checklist.',tools:['resumeio','canva'],body:[
['Write for the role first','Your CV should explain why you can do the advertised work. Remote readiness supports that case; it does not replace relevant experience. Read the vacancy and identify three priorities, such as customer communication, scheduling and accurate reporting. Match each priority to a real example from your history. Avoid filling the document with every task you have ever performed.'],
['A practical CV structure',['Header: professional name, dedicated email, city/country and optional portfolio or LinkedIn link.','Summary: two or three lines describing your relevant experience and target work.','Skills: tools and abilities you can discuss or demonstrate.','Experience: reverse chronological roles with concise achievement bullets.','Education and training: relevant qualifications, providers and dates.','Projects: selected examples that fill an experience gap.']],
['Fictional summary example','Example only: “Administrative coordinator with experience maintaining schedules, responding to enquiries and preparing weekly reports. Confident using spreadsheets and shared calendars to keep tasks visible. Seeking a remote operations support role with agreed working-hour overlap.” Adapt the structure to your own evidence. Do not copy experience, software skills or availability that you do not have.'],
['Turn responsibilities into useful evidence','Weak: “Responsible for customer emails.” Stronger fictional example: “Organised incoming enquiries by urgency, maintained a follow-up log and prepared a daily handover for the next shift.” If you have verified figures, add them; otherwise describe the workflow and result plainly. Show independent work, written updates and handovers through examples rather than repeating “excellent remote worker.”'],
['Keep the layout easy to read','Use a simple one-column document, consistent headings and selectable text. Follow the employer’s requested file format. For a PDF, copy the text into a plain-text editor and check the reading order. This is a practical check, not a guarantee that every applicant tracking system will parse the file. Keep an editable master and save a separate version for each role.'],
['Tailor without keyword stuffing','Use the vacancy’s terminology where it honestly describes your experience. If the employer asks for invoice tracking, a real invoice-related example is better than adding “invoicing” repeatedly to a skills list. Explain a career change by connecting existing skills to the new work, and use a project to demonstrate a missing practical skill.'],
['Before you send',['Check dates, job titles and contact details.','Remove national identity numbers, full home address and unrelated private information unless specifically and legitimately required.','Confirm every link works and portfolio access is appropriate.','Check that the opening half-page addresses the role’s main requirements.','Name the file clearly, proofread it aloud and keep a copy of the submitted version.']],
['Choosing a builder','A paid builder can help with formatting, but it cannot make weak evidence strong. Draft your content first, then compare export formats, recurring charges and editing access. If a plain document meets the employer’s requirements, there is no need to pay just to apply.']
],refs:[ref('Canva: resume templates','https://www.canva.com/resumes/templates/'),ref('Zety: plan and export information','https://zety.com/pricing')]},
{s:'best-ai-tools-for-job-applications',t:'Best AI Tools for Job Applications',c:'ai-tools',d:'Use writing and planning assistants to improve applications while keeping your experience accurate and your data private.',tools:['grammarly','notion'],body:[
['Choose a tool for a specific task','The useful question is not which AI tool is best overall, but which part of your application needs help. A writing assistant can help you review language, while an organised workspace helps track drafts and deadlines. This is a research-based guide using provider information and an editorial workflow; we have not performed a hands-on ranking of every product. Check current features and plan limits before subscribing.'],
['Match the task to the tool',{headers:['Task','Option to evaluate','Your responsibility'],rows:[['Review spelling, clarity and tone','Grammarly','Accept only edits that preserve your intended meaning.'],['Organise application notes and drafts','Notion','Check sharing permissions and keep personal documents private.'],['Practise answers with an assistant','A conversational tool you already use','Use fictional or redacted information and verify the output.'],['Build the final CV','An editable document or CV builder','Check formatting and every factual statement yourself.']]}],
['Start with an evidence bank','Before using AI, write a private list of real projects, tasks, tools and outcomes. Remove client names and confidential details from anything you plan to paste into an external service. Ask for help organising evidence, not inventing it. This gives the assistant a factual boundary and makes it easier to detect an unsupported claim.'],
['Prompt for a targeted CV review','Try: “Compare this redacted CV with this role description. List the three most important requirements that my CV does not clearly demonstrate. Quote the relevant requirement, identify existing evidence if present, and ask me questions where evidence is missing. Do not invent skills, employment dates or results.” Review the gaps and supply real information before asking for a rewrite.'],
['Prompt for a cover-letter draft','Try: “Using only the facts below, draft a concise cover letter with one relevant example. Keep the tone straightforward. Mark missing information with a question rather than filling it in. Do not claim familiarity with the company beyond the information I provide.” Replace generic enthusiasm with a specific reason for applying and remove language you would not naturally use.'],
['Practise interviews without outsourcing judgment','Ask for one interview question at a time and feedback on whether your answer includes context, action and outcome. The practice should help you tell your own story. Do not use an assistant to misrepresent your abilities or bypass an employer’s assessment rules. If the employer restricts AI use, follow those instructions.'],
['Final human review',['Verify all names, dates, qualifications and numbers.','Check that the application answers the actual question.','Remove confidential information and unnecessary personal details.','Read the draft aloud to ensure it sounds like you.','Check the final file and application fields before submitting.']],
['When to pay','Pay only after you identify a repeated task that the paid feature improves. A free tool and a careful editing process may be sufficient. No AI subscription can guarantee interviews, bypass screening or create genuine work experience.']
],refs:[ref('Grammarly: writing assistance','https://www.grammarly.com/'),ref('Notion: product and plans','https://www.notion.com/pricing')]},
{s:'prepare-for-remote-job-interview',t:'How to Prepare for a Remote Job Interview',c:'career-development',d:'Prepare your setup, examples and questions for a remote interview, including a practical backup plan.',tools:[],body:[
['Confirm the basics in writing','Check the date, the named timezone, meeting link, expected duration and interviewer’s name. Convert the time for the actual interview date because daylight-saving changes can affect the difference. Ask whether there will be a presentation, practical task or camera requirement. Save the recruiter’s verified contact details in case you cannot join.'],
['Test the real setup','Use the same device, headset, internet connection and room you will use on the day. Test the meeting platform ahead of time and check microphone permissions, lighting and camera position. Charge the device, turn off unnecessary notifications and close private documents. Avoid installing unfamiliar software merely because an unverified recruiter sent a link.'],
['Prepare four evidence-based stories',['A task you completed independently and how you tracked progress.','A misunderstanding you resolved through clear communication.','A problem you escalated early with a suggested solution.','A deadline you managed across competing priorities.']],
['Use a clear answer structure','Explain the situation briefly, identify your responsibility, describe your own action and finish with the outcome. A useful answer might explain how you noticed an overdue approval, checked the deadline, sent a concise reminder and informed the team of the next step. Use a genuine example; a modest result you can explain is better than an impressive invented story. Aim for clarity rather than memorising a script.'],
['Show how you would communicate remotely','Prepare a short sample update: “The draft is complete. I am waiting for approval on the final figures. If I receive confirmation by 14:00 UTC, I can send the report today; otherwise I will update the delivery estimate.” This demonstrates progress, a blocker and an actionable next step without unnecessary detail. Adapt the wording to the role and the team’s expectations.'],
['Questions worth asking',['Which working hours are fixed and how much timezone overlap is expected?','How do team members report progress or ask for help?','What would good performance look like in the first month?','What equipment and security arrangements are required?','Is the position employment or a contractor engagement, and what are the next steps?']],
['Have a connection-failure plan','Keep a charged phone and an alternative connection if available. If your connection fails, send a short message through the verified channel: explain what happened, say whether you can reconnect and offer an alternative. Do not spend the whole interview silently troubleshooting. If the problem persists, request a rescheduled slot and confirm it in writing.'],
['After the interview','Send a brief thank-you that mentions one relevant discussion point and any agreed follow-up. Record questions you struggled with while they are fresh. Keep applying elsewhere until you have a confirmed arrangement that you understand; an encouraging interview is not an offer.']
],refs:[ftc]},
{s:'best-free-project-management-tools',t:'Best Free Project Management Tools',c:'ai-tools',d:'Compare Trello, Asana, ClickUp and Notion by workflow, then test a free plan against a realistic project.',tools:['trello','asana','clickup','notion'],body:[
['Choose a workflow before choosing software','A useful project system tells you what needs doing, who is responsible and what happens next. Start with those questions before looking at dashboards or automations. Our comparisons use public provider information, not a claim of hands-on benchmarking. Free plans change; the linked pricing pages are the authority on current limits.'],
['A practical comparison',{headers:['Tool','Workflow to evaluate','Main trade-off to check'],rows:[['Trello','A visual board moving tasks between stages','Workspace, collaborator and board limits.'],['Asana','A shared task list with clear responsibilities','Team size and advanced planning features by plan.'],['ClickUp','Tasks and documents within one workspace','Storage, feature limits and setup complexity.'],['Notion','Notes and an application or project database','Team collaboration limits and the time needed to design a system.']]}],
['For a solo job seeker','Start with a board or table containing employer, role, deadline, application stage and next action. Keep a separate link to the version of the CV you submitted. The tool is doing its job if you can see today’s actions in less than a minute. You do not need a complicated workspace or premium automation to follow up on an application.'],
['For a small distributed team','Agree on one task owner, a due date and a definition of done. Put the decision or deliverable link on the task itself, rather than leaving the context scattered across chats. Add a blocked stage and a short explanation of what is needed. Even a feature-rich tool will fail if the team uses it inconsistently.'],
['Run a seven-day test',['Create one real project with a manageable number of tasks.','Invite only the collaborators who need access.','Test adding a task, assigning an owner and finding an overdue item.','Check mobile use, notification controls and exporting information.','List any paid feature you actually missed before considering an upgrade.']],
['Check the total cost','Compare the price for your actual number of users, the billing period and whether guest access changes the cost. Annual pricing can look lower per month while requiring an upfront payment. Confirm whether AI features, storage or advanced permissions are separate charges. Do not choose a system solely because the first month is discounted.'],
['Protect your information','Use invented data while learning the workspace. Before adding client records or private applications, review sharing permissions and your organisation’s rules. An accidentally public page can create a bigger problem than a missed deadline. Keep a practical export or backup route for important records.'],
['Our selection rule','For a simple visual pipeline, evaluate Trello first. For a task-led team, compare Asana and ClickUp. For a combined notes-and-database workflow, evaluate Notion. These are editorial starting points, not universal winners; keep the option that your actual workflow makes easiest to maintain.']
],refs:pmrefs},
{s:'improve-your-linkedin-profile',t:'How to Build a LinkedIn Profile That Attracts Recruiters',c:'career-development',d:'Make your headline, summary and work examples easier to understand without exaggerating your experience.',tools:['linkedin'],body:[
['Decide what your profile should communicate','Pick a target role or a small group of related roles before editing. A profile that tries to cover unrelated careers can leave a recruiter unsure where you fit. Write a one-sentence positioning statement: what you do, which skills support it and what kind of work you are seeking. Use that statement to guide the headline, About section and examples you feature.'],
['Write a descriptive headline','A headline can show a role and useful skills without claiming a position you have never held. Fictional example: “Operations Support | Scheduling, Reporting and Client Coordination | Open to Remote Opportunities.” If you are changing careers, lead with transferable abilities rather than inventing a senior title. Avoid guaranteed-results language and long strings of buzzwords.'],
['Use a three-part About section','Start with your professional focus. Follow with two or three genuine examples of work you can explain. Finish with the work you want and an appropriate contact route. Keep paragraphs short enough to scan. You can mention city or country and availability without publishing your home address, identity documents or private phone number.'],
['Make experience specific','Rewrite duties as examples of responsibility and outcome. Instead of “helped the team,” describe the report, process or coordination task you handled. Use verified figures where available and plain descriptions where they are not. Dates and titles should agree with your CV. Ask permission before sharing a client name, internal screenshot or confidential performance result.'],
['Add useful evidence',['A short case study using public or fictional data.','A relevant writing sample or presentation with clear authorship.','A completed learning project and a description of what you contributed.','A portfolio link that opens without unnecessary access requests.']],
['Review visibility and accuracy','Check the platform’s current visibility and job-seeking settings before publishing changes. Understand what is visible publicly and what requires sign-in. Do not assume that a setting guarantees confidentiality from every colleague or employer. Review your public profile as a visitor where possible and remove unnecessary personal information.'],
['Use the profile in a job-search routine','Follow relevant employers and read their actual vacancies. When contacting someone, reference a specific role or relevant discussion instead of sending a generic request for any job. Avoid repeatedly messaging people who do not respond. Keep a record of applications and follow-ups so you do not confuse networking with a formal application.'],
['A final five-minute check','Does the headline identify your direction? Does the first paragraph contain real skills? Are the most relevant achievements visible? Do portfolio links work? Are your CV and profile consistent? A clear profile improves understanding; it does not guarantee that recruiters will contact you.']
],refs:[ref('LinkedIn: professional profiles and jobs','https://www.linkedin.com/')]},
{s:'best-online-courses-for-remote-workers',t:'Best Online Courses for Remote Workers',c:'online-learning',d:'Compare four learning routes and choose a course that leads to a practical portfolio project.',tools:['coursera','udemy'],body:[
['Start with a skill gap','A course is useful when it closes a specific gap between your current skills and work you want to do. Review several eligible vacancies and write down repeated tasks. If you already meet the core requirements, a portfolio project or better application may be more useful than another certificate. Do not buy training just because a sales page promises a remote career.'],
['Four routes to compare',{headers:['Course or programme','Focus','Suggested follow-up project'],rows:[['<a href="https://grow.google/certificates/project-management/" target="_blank" rel="noopener noreferrer">Google Project Management</a>','Project coordination and planning','A project brief, schedule, risk log and status update.'],['<a href="https://grow.google/certificates/data-analytics/" target="_blank" rel="noopener noreferrer">Google Data Analytics</a>','Working with and explaining data','A cleaned public dataset and a short findings report.'],['<a href="https://grow.google/certificates/it-support/" target="_blank" rel="noopener noreferrer">Google IT Support</a>','IT support foundations','A fictional support-ticket log and troubleshooting guide.'],['<a href="https://www.coursera.org/learn/learning-how-to-learn" target="_blank" rel="noopener noreferrer">Learning How to Learn</a>','Study methods and learning habits','A four-week study plan with practice and review sessions.']]}],
['How we selected these options','These are research-based options drawn from official programme descriptions. They cover different learning needs and are not a ranking of job-placement outcomes. We have not completed every course or verified an individual learner’s results. Read the current syllabus, language options and assessment requirements before choosing. A programme’s availability does not establish that its employers hire in your country.'],
['Compare the real cost','Check the price displayed for your location, whether the course uses a subscription and what happens after a trial. A free account or a “join for free” button does not necessarily include a free certificate. Review cancellation instructions, paid assessment requirements and any assistance options on the current enrolment page. Avoid relying on a price copied from an old blog post.'],
['Build evidence while studying','For each topic, create a small deliverable that resembles real work. A scheduling lesson could become a fictional project calendar; a data lesson could become a documented cleaning exercise. Keep notes about the problem, your approach, checks and limitations. These explanations help an employer understand your contribution more than a certificate image alone.'],
['A manageable weekly routine',['Choose one learning outcome for the week.','Schedule a few focused study blocks that fit your existing responsibilities.','Complete a practice task without copying the instructor’s solution.','Review mistakes and update your notes.','Save one finished output with a clear explanation.']],
['When a short course is better','If your gap is narrow, such as spreadsheet lookups or writing concise reports, compare a focused module with a longer programme. Review the instructor, syllabus and sample material on any marketplace. Choose based on the task you need to perform, not the largest discount or the highest advertised number of hours.'],
['Before enrolling','Write down the job task you want to improve, the output you will create, the cost you can afford and the time you can commit. If you cannot answer those questions, postpone payment and try a free practice exercise first.']
],refs:[ref('Google: Project Management programme','https://grow.google/certificates/project-management/'),ref('Google: Data Analytics programme','https://grow.google/certificates/data-analytics/'),ref('Google: IT Support programme','https://grow.google/certificates/it-support/'),ref('Learning How to Learn: official course','https://www.coursera.org/learn/learning-how-to-learn')]},
{s:'start-freelancing-without-experience',t:'How to Start Freelancing Without Experience',c:'freelancing',d:'Choose a narrow service, create honest samples, scope a small project and check how you will get paid.',tools:['upwork','fiverr'],body:[
['Start with one deliverable','“I can do anything online” is difficult for a buyer to evaluate. Choose one specific output you can complete reliably: clean a spreadsheet, proofread a short document, organise a calendar or prepare a small set of social posts. Define what you will deliver, what the client must provide and what is outside the scope. This makes practice, pricing and quality checks easier.'],
['Create samples without pretending they were paid work','Use a fictional brief or public information. Label the result as a sample project and explain your decisions. A spreadsheet sample might include the original invented data, cleaned version and a short error checklist. Do not invent testimonials, client logos or revenue results. If you volunteer, agree on the task and obtain permission before displaying the work.'],
['Write a small service offer','Fictional example: “I will organise one spreadsheet of up to 300 rows, standardise date formats, flag duplicates and provide a summary of changes. You provide the file and your formatting requirements. The scope includes one clarification round; research and data entry from other sources are excluded.” Adjust the numbers to what you can actually deliver. A clear offer helps prevent unexpected work.'],
['Choose a client-finding route','You can evaluate freelance marketplaces, relevant professional communities or your existing network. Check platform country eligibility, identity checks, proposal charges, fees and withdrawal options before building your profile. If work is found through a platform, follow its communication and payment rules. Do not assume that a payout method available in another country will work for your bank.'],
['Price the whole job','Estimate preparation, delivery, communication and revision time. Include platform charges and currency-conversion costs when calculating what you would receive. A modest initial project can be useful, but repeated unbounded free work is not a sustainable route. Agree on deliverables, review rounds, deadlines and payment arrangements in writing before starting.'],
['A first-project checklist',['Confirm the client and the source of the work.','Clarify inputs, deliverables and acceptance criteria.','Use a small milestone or the platform’s supported payment protection where appropriate.','Send a progress update before the deadline.','Run a quality check and provide a concise handover.']],
['Protect yourself from scams','Do not buy gift cards, forward money or pay a deposit to unlock work. Be cautious of overpayments followed by refund requests and of files requiring unfamiliar software. Do not disclose sensitive account information to a prospective client. Verify any identity or payment request through the platform’s official process.'],
['Review after delivery','Record your actual hours, what caused delays and what you would clarify next time. Ask for honest feedback without pressuring the client. Improve the offer before taking on a larger project. Your first useful milestone is a well-delivered, properly paid task, not a claim of instant full-time income.']
],refs:[ref('Upwork: official platform','https://www.upwork.com/'),ref('Fiverr: official marketplace','https://www.fiverr.com/'),ftc]},
{s:'build-a-remote-career-from-africa',t:'How to Build a Remote Career From Africa',c:'remote-jobs',d:'Check hiring geography, working hours, infrastructure and payment arrangements before investing in a remote job search.',tools:['linkedin','upwork'],body:[
['Begin with the country you work from','Africa is not a single hiring jurisdiction. Employers and platforms may support some countries and not others. Search using your actual residence and work location, and read the employer’s requirements before applying. A role described as worldwide still needs confirmation of the working arrangement. Do not enter a different country just to bypass a filter.'],
['Find genuinely eligible opportunities','Use boards that let you filter by country or timezone, then verify the employer’s own description. Check whether the vacancy is employment, a contractor engagement or a freelance project. An employer may need a supported local hiring arrangement even when the work is online. Ask a clear question early: “Can this role be performed by someone residing and working in my country?”'],
['Plan the practical working setup','List your normal internet connection, a backup option, device reliability and power arrangements. Test your actual ability to join a call, upload a large file and work during the required hours. You do not need to promise uninterrupted availability; describe a realistic backup plan and how you will inform the team if something fails. Avoid expensive equipment purchases before you understand the role’s requirements.'],
['Explain timezone overlap precisely','State your timezone and the hours you can reliably work. Use UTC when communicating availability, then confirm the employer’s local-time conversion for the actual date. Employers using daylight saving may shift their local working hours relative to yours. Agree on which meetings are fixed and which tasks can be completed asynchronously.'],
['Clarify payment before accepting',['Confirm the payer’s legal identity and the proposed work arrangement.','Ask which currency and supported payment method will be used.','Check that your own bank or provider can receive that type of payment.','Understand withdrawal, conversion and intermediary fees.','Agree the payment schedule and keep written records.']],
['Show evidence that travels well','A concise portfolio can help demonstrate skills across borders. Include a completed sample, the problem it solves and a short explanation of your process. Use public or fictional data and avoid confidential employer material. Clear writing, reliable follow-up and an understandable CV are useful evidence of how you will work in a distributed team.'],
['A focused weekly routine','Choose a target role, shortlist eligible vacancies and tailor a manageable number of applications. Review whether rejections come from geography, experience or application quality before changing direction. If location restrictions dominate, search for worldwide contractor work or employers explicitly hiring in your country rather than repeatedly applying to country-restricted roles.'],
['Keep expectations grounded','Remote work does not remove taxes, contract obligations or local rules. Get qualified local advice when needed for your circumstances. Never pay a recruiter to secure a job, and do not treat a course or platform subscription as a guarantee of international employment.']
],refs:[locations,ref('Himalayas: jobs by country','https://himalayas.app/jobs/countries'),ftc]},
{s:'best-skills-to-learn-for-remote-jobs',t:'Best Skills to Learn for Remote Jobs',c:'career-development',d:'Prioritise skills by the work you want to do and prove them with practical projects.',tools:['coursera','udemy'],body:[
['Use vacancies as your curriculum','There is no single skill that qualifies everyone for remote work. Choose a role family and review a small set of current vacancies open to your location. Group repeated requirements into tasks, tools and knowledge. Prioritise the gaps that appear repeatedly and are necessary for the work, rather than the newest topic on social media.'],
['Build foundations that support many roles',{headers:['Skill','Practice exercise','Evidence to keep'],rows:[['Clear written communication','Write a status update with progress, blocker and next action','Before-and-after edits and the final update.'],['Spreadsheets','Clean sample data and summarise totals','A workbook with checks and a short explanation.'],['Organisation','Plan a project with owners and deadlines','A task board and weekly review.'],['Research','Answer a practical question using primary sources','A short brief with dated source links.'],['Problem solving','Investigate a fictional support issue','A troubleshooting log and escalation note.']]}],
['Add one role-specific skill','For operations support, practise scheduling and process documentation. For content coordination, practise brief writing and editing. For technical support, study the relevant systems and troubleshooting basics. These are learning directions rather than guarantees of demand. Confirm the actual tasks and qualifications in your target vacancies before choosing a course.'],
['Learn through a complete task','A useful learning project has an input, a decision and an output. For example, take a fictional customer enquiry log, standardise categories, identify overdue items and prepare a handover. Document your assumptions and how you checked errors. This shows more than a screenshot of an unfinished tutorial.'],
['Choose training after choosing the outcome','Compare a free tutorial, a focused module and a structured programme. Read the syllabus and check whether there is meaningful practice. A longer course is not automatically better. If a certificate is required in your target role, confirm the exact credential before paying for something with a similar title.'],
['A four-week learning cycle',['Week 1: choose one recurring requirement and assess your starting level.','Week 2: learn the basics and complete guided practice.','Week 3: repeat the task independently using different data.','Week 4: review mistakes, finish a sample and explain the result.']],
['Know when to start applying','Do not wait until you meet every desirable requirement. Apply when you can honestly demonstrate the core work and explain how you are addressing remaining gaps. Keep learning from actual application feedback. If employers repeatedly ask for a specific skill you lack, adjust your next learning project rather than collecting unrelated certificates.'],
['Your next step','Choose one target vacancy, one important skill gap and one deliverable to finish this week. Keep the scope small enough to complete and evaluate. Consistent practice creates usable evidence; a long list of tools on your CV does not.']
],refs:[ref('Google: career certificate fields','https://grow.google/certificates/'),ref('Coursera: professional programmes','https://www.coursera.org/professional-certificates')]},
{s:'work-remotely-for-international-companies',t:'How to Work Remotely for International Companies',c:'remote-jobs',d:'Understand hiring locations, prepare a targeted application and clarify the arrangement before accepting international remote work.',tools:['linkedin'],body:[
['Separate remote work from work-from-anywhere','An international company may hire only in countries where it can employ or engage workers. A remote role describes where the work is performed relative to an office; it does not necessarily allow any residence or travel destination. Read location conditions and ask for clarification before investing in a long assessment.'],
['Choose a target role and hiring route','Start with work you can already demonstrate. Look at employer careers pages and reputable boards, then identify whether the role is direct employment, a local hiring arrangement or a contractor project. These arrangements can differ in benefits, expenses and responsibilities. Do not assume they are equivalent because the job title and advertised payment look similar.'],
['Build an employer shortlist','Choose organisations whose work relates to your skills. For each one, record the official careers URL, relevant roles, hiring countries and working-hour requirements. Check the original listing rather than relying only on a repost. A smaller shortlist makes it easier to write a specific application and notice inconsistencies in recruiter messages.'],
['Tailor the application around evidence','Connect the employer’s priorities to two or three real examples. Explain what you handled, the tools you used and the outcome you can support. Add your actual work location and timezone availability where relevant. If you have never held a remote role, show independent delivery, written communication and reliable handovers from other work.'],
['Questions to resolve before accepting',['Can the work be performed from your country of residence?','What is the employment or contractor arrangement?','Which hours and meetings are mandatory?','Who provides equipment and required software?','What currency, payment method and schedule apply?','What confidentiality, security and travel restrictions apply?']],
['Check payment and local obligations','Confirm that the proposed payment route works for your own account and understand fees before accepting. Keep written records of the arrangement. Tax, employment and business-registration questions depend on your circumstances; obtain qualified advice rather than assuming that online work is exempt from local requirements.'],
['Verify the recruiter','Compare the email domain and application process with the real company website. Contact the company through an independently found official route if anything is unclear. Do not pay a placement fee or buy equipment from a recruiter-selected seller to unlock a job. Protect identity documents and bank information until there is a legitimate, verified reason to provide them.'],
['Start with a sustainable routine','Track applications, deadlines and agreed follow-ups. Review results by role and eligibility, not just the number submitted. If the same geographical restriction appears repeatedly, change the employer shortlist. If you reach interviews but struggle to demonstrate a core skill, build a relevant practice project and update your examples.']
],refs:[locations,ftc]},
{s:'best-resume-builders-compared',t:'Best Resume Builders Compared',c:'resume-cv',d:'Compare a plain document, Canva, Resume.io and Zety before paying for a CV builder.',tools:['resumeio','canva'],body:[
['A builder formats evidence; it does not create it','Draft your work history, achievements and target-role summary before choosing a template. The best option for you is the one that produces a readable file in the employer’s requested format at a cost you understand. This is a research-based comparison of workflow and published information, not a hands-on test or a guarantee of applicant tracking system performance.'],
['Compare the options',{headers:['Option','When to consider it','What to check'],rows:[['An editable word-processing document','You want control and a simple layout','Availability of the required export format and consistent spacing.'],['<a href="https://www.canva.com/resumes/templates/" target="_blank" rel="noopener noreferrer">Canva</a>','You want visual template choices','Whether chosen elements are free and whether text reads in the right order.'],['<a href="https://resume.io/" target="_blank" rel="noopener noreferrer">Resume.io</a>','You prefer a guided builder','Current export access, editing limits and subscription terms; verify in the provider’s checkout.'],['<a href="https://zety.com/pricing" target="_blank" rel="noopener noreferrer">Zety</a>','You want structured resume-building options','Which download formats are included in your selected plan and what renews.']]}],
['Test the final file, not just the template','Create a short sample before entering your full history. Export it in the format you need, reopen it on another device and copy the text into a plain-text editor. Check headings, dates, bullet order and links. A visually attractive template can still be hard to read. No simple test can guarantee compatibility with every employer’s system, so follow the application instructions.'],
['Understand the checkout','Check the full billing period, the amount charged now, any trial end date and the next renewal. Do not assume that a low entry price is a one-time payment. Save a copy of the terms you accept and locate the cancellation controls before subscribing. If the plan does not clearly include your required download format, ask the provider before paying.'],
['Keep your data portable','Store a separate editable copy of your content outside the builder. This helps if access ends, a template changes or you want to use another service. Review account and document privacy settings before uploading. Avoid adding identity numbers, full home addresses or private references unless there is a legitimate application requirement.'],
['Our decision framework',['Choose a plain document when simplicity and control matter most.','Evaluate Canva when you need template flexibility, using a restrained layout for standard applications.','Evaluate guided builders when their structure saves you meaningful time.','Pay only when the required export and editing features justify the actual cost.']],
['Before sending','Check that the document accurately represents you and is tailored to the vacancy. The clearest template will not fix a mismatch between the job requirements and the examples you provide. Keep the employer’s instructions, truthful content and easy reading ahead of decorative design.']
],refs:[ref('Canva: official resume templates','https://www.canva.com/resumes/templates/'),ref('Zety: official plans and export information','https://zety.com/pricing'),ref('Resume.io: verify current options directly','https://resume.io/')]},
{s:'remote-jobs-without-degree',t:'Remote Jobs That Do Not Require a Degree',c:'remote-jobs',d:'Identify roles where practical evidence may matter more than a degree and check each employer’s actual requirements.',tools:['linkedin','coursera'],body:[
['Read the requirement carefully','Some vacancies accept equivalent experience, some list a degree as preferred and others make it mandatory. These are different conditions. A role that does not require a degree can still require specialist knowledge, experience, language ability or a licence. Remote working does not remove those requirements. Use the actual employer description rather than a broad “no degree needed” headline.'],
['Role families to investigate',{headers:['Role family','Evidence you could demonstrate','Important restriction to check'],rows:[['Customer support','Clear replies, problem diagnosis and escalation','Language, shifts and permitted work countries.'],['Administrative support','Scheduling, records and follow-through','Required business experience and availability.'],['Content assistance','Writing samples and careful editing','Subject knowledge and portfolio expectations.'],['Sales support','Accurate lead records and professional follow-up','Targets, calls and payment structure.'],['Web or technical work','Completed projects and explanation of decisions','Actual technical assessment and experience level.']]}],
['Build a proof-based application','Choose one recurring task from eligible vacancies and create a realistic sample using public or fictional information. Explain the brief, your approach, quality checks and limitations. For an administrative role, this could be a meeting pack and action tracker. For content support, provide an original draft and an edited version. Label samples honestly instead of presenting them as paid client work.'],
['Explain your learning clearly','Include relevant courses and projects, but distinguish attending a course from gaining a formal qualification. List the correct provider, title and completion status. If you are self-taught, explain what you can do and link to evidence. Do not invent a degree, imply a licence you lack or use a credential title that the provider did not award.'],
['Handle an experience gap','A career change often includes useful transferable work. Identify examples of customer communication, record keeping, problem solving or independent delivery. Connect the example to the new role’s actual tasks. Avoid apologising throughout the application for not having a degree; concentrate on the criteria you meet and be straightforward about any mandatory requirement you do not meet.'],
['Before paying for training',['Confirm whether the vacancy requires a particular credential.','Check whether a free practice project would address the gap.','Review the syllabus and total cost of any course.','Do not assume that a certificate guarantees a job or hiring-country eligibility.']],
['Keep the search realistic','Use skill and task keywords in addition to “no degree.” Verify work location, hours and employment arrangement. Be cautious of advertisements promising unusually high earnings for simple tasks with no screening. Never pay someone to secure a vacancy or submit sensitive documents to an unverified recruiter.'],
['Your next step','Find three current roles for which a degree is not mandatory and list their shared practical requirements. Build one piece of evidence for the most important gap. That gives you a focused learning goal and a stronger application than applying to every vacancy labelled entry-level.']
],refs:[locations,ftc]},
{s:'best-productivity-tools-working-from-home',t:'Best Productivity Tools for Working From Home',c:'ai-tools',d:'Build a small, affordable tool setup for tasks, notes, communication and focused work.',tools:['trello','notion','grammarly'],body:[
['Use fewer tools with clearer jobs','Productivity software is useful when it reduces a specific friction: forgotten tasks, missing context, unclear writing or repeated manual work. Adding several overlapping apps can create more places to check. Start by identifying the problem and assigning one tool to each need. If your employer already provides a system, follow its approved workflow rather than creating a separate one.'],
['A minimal setup to evaluate',{headers:['Need','Starting option','Good sign it is working'],rows:[['Daily tasks','A simple task list or Trello board','You can identify the next action without searching chats.'],['Reference notes','A document folder or Notion workspace','Instructions and decisions are easy to find.'],['Clear written updates','Careful editing with optional Grammarly support','Messages make the request, owner and deadline clear.'],['Focused work','Calendar blocks and device notification controls','You complete a defined task before switching contexts.']]}],
['Design a start-of-day routine','Review deadlines, choose the few outcomes that matter today and check whether you need information from someone else. Ask early for any missing input. Keep a short list of next actions that are small enough to start. “Finish project” is vague; “check the three unresolved figures and send the approval request” is actionable.'],
['Use a standard status update','A useful update covers what is done, what remains, what is blocked and when the next milestone is expected. Link to the deliverable rather than sending multiple versions in different chats. If the deadline changes, explain the reason and give an updated estimate. This communication habit often solves problems that another app cannot.'],
['Separate learning from production work','Try new tools with sample information before relying on them for a live deadline. Set a time limit for setup. If you spend more time redesigning the dashboard than completing tasks, simplify the system. Keep important files in an approved location and avoid making a public link just to share something quickly.'],
['Review costs and permissions','Check user limits, file storage, export options and what becomes paid after a trial. Do not upload client records to an unapproved AI or automation service. For shared tools, verify who can view, edit or invite others. Use account protection supported by the service and keep recovery information private.'],
['A seven-day experiment',['Record one recurring work problem.','Choose one change to your tool setup or routine.','Use it for a normal working week.','Measure a practical outcome, such as fewer missed follow-ups.','Keep, adjust or remove the change based on the result.']],
['When to upgrade','Upgrade when a specific limitation blocks useful work and the benefit justifies the full cost. Do not purchase software merely to feel prepared for remote work. A well-maintained free system with clear communication can be more effective than several paid subscriptions used inconsistently.']
],refs:[ref('Trello: plans','https://trello.com/pricing'),ref('Notion: plans','https://www.notion.com/pricing'),ref('Grammarly: writing assistance','https://www.grammarly.com/')]}];
